package tor

import (
	"strings"
	"testing"
)

func TestApplyTorrcPlatformDefaultsDebianKeepsTemplate(t *testing.T) {
	base := "RunAsDaemon 1\nCookieAuthFile /var/run/tor/control.authcookie\n"

	got := applyTorrcPlatformDefaults(base, false)

	if got != base {
		t.Fatalf("expected unchanged template, got %q", got)
	}
}

func TestApplyTorrcPlatformDefaultsArchRewritesDaemonSettings(t *testing.T) {
	base := strings.Join([]string{
		"# Dynamic torrc file generated by anonsurf",
		"RunAsDaemon 1",
		"CookieAuthFile /var/run/tor/control.authcookie",
		"CookieAuthentication 1",
		"",
	}, "\n")

	got := applyTorrcPlatformDefaults(base, true)

	for _, want := range []string{
		"RunAsDaemon 0",
		"CookieAuthFile /var/lib/tor/control.authcookie",
		"User tor",
		"DataDirectory /var/lib/tor",
	} {
		if !strings.Contains(got, want) {
			t.Errorf("expected %q in rendered torrc:\n%s", want, got)
		}
	}
	for _, unwanted := range []string{
		"RunAsDaemon 1",
		"/var/run/tor/control.authcookie",
	} {
		if strings.Contains(got, unwanted) {
			t.Errorf("did not expect %q in rendered torrc:\n%s", unwanted, got)
		}
	}
}

func TestApplyTorrcPlatformDefaultsArchKeepsExistingUser(t *testing.T) {
	base := "RunAsDaemon 1\nUser tor\n"

	got := applyTorrcPlatformDefaults(base, true)

	if strings.Count(got, "User tor") != 1 {
		t.Errorf("expected a single User directive, got:\n%s", got)
	}
}
